-claim-appraisal/home-insurance-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, HOA & Farm Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/commercial-hoa-farm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Microburst Claim Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/wind-microburst-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Frozen Pipe Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/water-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wildfire Claim Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/wildfire-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Snow Load & Ice Dam Appraisal","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/snow-load-ice-dam-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/claim-estimate-review/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire Services","url":"https://idahoinsuranceappraiser.com/property-claim-appraisal/appraisal-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Hail damage","Wildfire claims","Snow load damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://idahoinsuranceappraiser.com/#website","url":"https://idahoinsuranceappraiser.com/","name":"Idaho Insurance Appraiser","publisher":{"@id":"https://idahoinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#webpage","url":"https://idahoinsuranceappraiser.com/claim-terms-defined/","name":"Insurance Claim Terms Defined | Searchable Glossary","description":"Searchable glossary of insurance claim terms: actual cash value, holdback, umpire, snow load, O&P and more, defined in plain English.","inLanguage":"en-US","isPartOf":{"@id":"https://idahoinsuranceappraiser.com/#website"},"about":{"@id":"https://idahoinsuranceappraiser.com/#business"},"publisher":{"@id":"https://idahoinsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#primaryimage","url":"https://idahoinsuranceappraiser.com/assets/img/photos/paperwork.webp","width":960,"height":641,"caption":"Notepad, calculator, glasses and pen on a white desk"},"breadcrumb":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#breadcrumb"},"mainEntity":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://idahoinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim terms defined","item":"https://idahoinsuranceappraiser.com/claim-terms-defined/"}],"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#breadcrumb"},{"@type":"DefinedTermSet","name":"Property insurance claim terms","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual cash value (ACV)","description":"Replacement cost minus depreciation. Often the first payment on a replacement-cost claim.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Additional living expense (ALE)","description":"Coverage for extra costs of living elsewhere while your home is being repaired after a covered loss.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Amount of loss","description":"The dollar value of a covered loss. This is what an appraisal panel decides.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal clause","description":"The policy condition that allows either party to demand appraisal when they disagree on the amount of loss.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraisal award","description":"The written decision on the amount of loss, binding once signed by two of the three panel members.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Appraiser","description":"The person each side appoints to value the loss under the appraisal clause.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Bad faith","description":"A legal claim that an insurer unreasonably handled or denied a claim. Decided by courts, not appraisal panels.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Collapse coverage","description":"Policy language covering the sudden falling-in of a building or part of it, often tied to causes such as the weight of snow or ice.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Coinsurance","description":"A commercial policy clause that can reduce payment if a property is insured for less than a required percentage of its value.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Contents coverage","description":"Coverage for personal property, often called Coverage C on a homeowners policy.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Cosmetic damage exclusion","description":"An endorsement that excludes damage affecting only appearance, often applied to metal roofs after hail.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Coverage A","description":"Dwelling coverage on a homeowners policy, the limit for the house itself.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Declarations page","description":"The summary page of a policy listing coverages, limits, deductibles and endorsements.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss the policyholder pays before the insurer pays.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Depreciation","description":"The reduction in value due to age, wear or obsolescence, subtracted from replacement cost to find actual cash value.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Direct physical loss","description":"A common trigger phrase in property policies describing tangible damage to property.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Disinterested appraiser","description":"An appraiser with no financial stake in the outcome or the repair work.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Dwelling fire policy","description":"A policy form often used for rental properties, with different terms than a homeowners policy.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Extended replacement cost","description":"An endorsement that pays above the dwelling limit, often by a set percentage, if rebuilding costs exceed it.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation withheld until repairs are completed.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Ice dam","description":"A ridge of ice at the eaves that traps meltwater, which can back up under roofing and into the home.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Line item","description":"A single entry in an estimate describing a task, quantity and price.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Loss of use","description":"Coverage that includes additional living expense and fair rental value after a covered loss.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Matching","description":"The issue of whether undamaged materials must be replaced so repairs match in color and style.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps taken after a loss to prevent further damage, such as tarping or water extraction.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Ordinance or law coverage","description":"Coverage for added costs of bringing a damaged building up to current codes.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Other structures","description":"Coverage for detached structures such as fences, garages and sheds, often called Coverage B.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Overhead and profit (O&P)","description":"A general contractor’s charge for coordinating a job, often 10% overhead and 10% profit.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Percentage deductible","description":"A deductible calculated as a percentage of the dwelling limit rather than a flat amount.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Proof of loss","description":"A sworn statement of the amount claimed, which insurers may request within a set time.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Public adjuster","description":"A licensed professional who represents a policyholder in negotiating the overall claim.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Recoverable depreciation","description":"Depreciation that can be paid once repairs or replacement are completed under a replacement-cost policy.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Replacement cost value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, without deduction for depreciation.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Scope of loss","description":"The list of damaged items and the repairs needed. Many disputes are about scope rather than price.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Snow load","description":"The weight of accumulated snow and ice on a roof, measured in pounds per square foot.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Square (roofing)","description":"100 square feet of roof surface.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Subrogation","description":"The insurer’s right to recover what it paid from a third party responsible for the loss.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Suit limitation clause","description":"Policy language setting the time to file a lawsuit against the insurer.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an estimate after the initial review.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Surplus lines insurer","description":"An insurer not licensed in the standard market that can cover hard-to-place risks.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third panel member who decides items the two appraisers can’t agree on.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Wildland-urban interface (WUI)","description":"Areas where homes meet or mix with undeveloped wildland vegetation, with higher wildfire risk.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price property repairs.","inDefinedTermSet":{"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}}],"@id":"https://idahoinsuranceappraiser.com/claim-terms-defined/#definedtermset"}]}</script>
</head>
